<?php require __DIR__.'/../includes/bootstrap.php'; if(user()){header('Location: '.url());exit;} $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){ check_csrf(); $email=trim($_POST['email']??''); $pdo=db(); $ip=$_SERVER['REMOTE_ADDR']??''; $blocked=$pdo->prepare('SELECT COUNT(*) FROM login_attempts WHERE ip_address=? AND attempted_at>DATE_SUB(NOW(),INTERVAL 15 MINUTE)'); $blocked->execute([$ip]); if($blocked->fetchColumn()>=5){$error='Too many sign-in attempts. Please try again in 15 minutes.';} else {$s=$pdo->prepare('SELECT * FROM users WHERE email=? LIMIT 1');$s->execute([$email]);$u=$s->fetch(); $role=strtoupper((string)($u['role']??'')); $status=strtoupper((string)($u['status']??'')); if($u&&password_verify($_POST['password']??'',$u['password'])&&$status==='ACTIVE'&&(int)$u['email_verified']===1){session_regenerate_id(true);$_SESSION['authenticated']=true;$_SESSION['user']=['id'=>(int)$u['id'],'name'=>$u['first_name'].' '.$u['last_name'],'role'=>$role];$pdo->prepare('UPDATE users SET last_login=NOW() WHERE id=?')->execute([$u['id']]);$pdo->prepare('DELETE FROM login_attempts WHERE email=? OR ip_address=?')->execute([$email,$ip]);log_action((int)$u['id'],'LOGIN','user',(int)$u['id'],'User logged in');header('Location: '.url($role==='ADMIN'?'admin/index.php':'customer/dashboard.php'));exit;} $pdo->prepare('INSERT INTO login_attempts(email,ip_address) VALUES(?,?)')->execute([$email,$ip]);$error=($u&&$status==='PENDING_VERIFICATION')?'Your account has not been verified yet. Use the verification link below.':'Invalid email or password.'; }} $pageTitle='Login';require __DIR__.'/../includes/header.php';?><div class="panel"><h1>Welcome back</h1><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Email</label><input required type="email" name="email"><label for="login-password">Password</label><div class="password-field"><input required id="login-password" type="password" name="password" autocomplete="current-password"><button class="password-toggle" type="button" data-password-toggle="login-password" aria-label="Show password" aria-pressed="false"><svg class="password-toggle-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M2.5 12s3.5-6 9.5-6 9.5 6 9.5 6-3.5 6-9.5 6-9.5-6-9.5-6Z"></path><circle cx="12" cy="12" r="2.75"></circle></svg></button></div><p><button type="submit">Sign in</button></p><p><a href="verify.php">Verify account</a> &middot; <a href="forgot-password.php">Forgot password?</a> &middot; <a href="register.php">Create account</a></p></form></div><?php require __DIR__.'/../includes/footer.php'; ?>
